new=json.load(open('frontend/validation.json'))
def delta(a,b,p=''):
 if type(a)!=type(b): print(p,a,b)
 elif isinstance(a,dict):
  for k in a.keys()|b.keys(): delta(a.get(k),b.get(k),p+'/'+k)
 elif isinstance(a,list):
  if len(a)!=len(b): print(p,'length',len(a),len(b))
  for i,(x,y) in enumerate(zip(a,b)):delta(x,y,p+'/'+str(i))
 elif a!=b: print(p,repr(a),repr(b))
delta(old,new)
